<?php
class AdminNtCreatorRewardsImportController extends ModuleAdminController
{
    public function __construct(){parent::__construct();$this->bootstrap=true;}
    public function postProcess(){if(Tools::isSubmit('submitNtcrImport')){$f=$_FILES['ntcr_xlsx']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK)$this->errors[]='XLSX yüklenemedi.';else try{$id=NtcrService::import($f['tmp_name'],$f['name'],(int)$this->context->shop->id,(int)$this->context->employee->id);$this->confirmations[]='Rapor taslak olarak aktarıldı. Parti #'.$id;}catch(Exception $e){$this->errors[]=$e->getMessage();}}if(Tools::isSubmit('submitNtcrRematch'))try{$r=NtcrService::rematchDraftRows((int)$this->context->shop->id,(int)$this->context->employee->id);$this->confirmations[]=$r['ready'].' kayıt eşleşti; '.$r['unmatched'].' kayıt eşleşmedi; '.$r['conflicts'].' çakışma bulundu.';}catch(Exception $e){$this->errors[]=$e->getMessage();}if(Tools::isSubmit('submitNtcrApprove'))try{$n=NtcrService::approve((int)Tools::getValue('id_batch'),Tools::getValue('fx_rate'),(int)$this->context->employee->id,(int)$this->context->shop->id);$this->confirmations[]=$n.' eşleşen yayıncının puan farkı işlendi.';}catch(Exception $e){$this->errors[]=$e->getMessage();}parent::postProcess();}
    public function initContent(){parent::initContent();$b=Db::getInstance()->executeS('SELECT b.*,(SELECT COUNT(*) FROM `'._DB_PREFIX_.'ntcr_source_row` r WHERE r.id_batch=b.id_batch AND r.validation_status=\'ready\') ready_count,(SELECT COUNT(*) FROM `'._DB_PREFIX_.'ntcr_source_row` r WHERE r.id_batch=b.id_batch AND r.validation_status<>\'ready\') excluded_count FROM `'._DB_PREFIX_.'ntcr_batch` b WHERE b.id_shop='.(int)$this->context->shop->id.' ORDER BY id_batch DESC');$this->context->smarty->assign(array('ntcr_batches'=>$b,'ntcr_token'=>Tools::getAdminTokenLite('AdminNtCreatorRewardsImport')));$this->content=$this->context->smarty->fetch(_PS_MODULE_DIR_.'ntcreatorrewards/views/templates/admin/import.tpl');$this->context->smarty->assign('content',$this->content);}
}
